//! Logos lexer generation from the grammar's token declarations.
//!
//! Local patch (see /vendor/PATCHES.md): the grammar file is the single
//! source of truth for token names and literal spellings. Literal tokens
//! (`Query='query'`) become `#[token("query")]` variants; tokens without a
//! literal (`Name='<name>'`, `Whitespace`) take their logos attribute
//! arguments from the [`LexerSpec`] supplied by the consumer's build script.
//! Generation fails loudly when a token has neither, so lexer drift against
//! the grammar is a build error, not a runtime surprise.

use std::fmt::Write;
use std::path::Path;

use crate::frontend::ast::{AstNode, File, Named};
use crate::frontend::parser::{NodeRef, Parser};

/// Logos attribute arguments for tokens the grammar declares without a
/// literal spelling.
pub struct LexerSpec<'a> {
    /// `(token name, verbatim logos attribute arguments)`, e.g.
    /// `("Name", r#"r"[A-Za-z_][A-Za-z0-9_]*""#)`. The arguments are spliced
    /// into `#[regex(...)]` unchanged, so flags like `allow_greedy = true`
    /// can be appended after the pattern.
    pub patterns: &'a [(&'a str, &'a str)],
}

/// Generates `lexer.rs` in `out_dir` from the grammar's token declarations.
///
/// The generated module expects to live next to the generated parser module
/// (it imports `super::parser::{Diagnostic, Span}`) and provides the
/// `Token` enum, `LexerError`, `tokenize`, and `Token::literal_text`.
pub fn generate_lexer(grammar: &str, out_dir: &str, spec: &LexerSpec<'_>) -> std::io::Result<()> {
    let source = std::fs::read_to_string(grammar)?;
    let mut diags = Vec::new();
    let cst = Parser::new(&source, &mut diags).parse(&mut diags);

    let Some(file) = File::cast(&cst, NodeRef::ROOT) else {
        return Err(invalid_data("grammar file has no root".to_string()));
    };

    let mut variants = String::new();
    let mut literal_arms = String::new();
    let mut missing = Vec::new();

    for decl in file.token_decls(&cst) {
        let Some((name, _)) = decl.name(&cst) else {
            continue;
        };
        let literal = decl.symbol(&cst).and_then(|(symbol, _)| {
            let inner = symbol
                .strip_prefix('\'')
                .and_then(|symbol| symbol.strip_suffix('\''))
                .unwrap_or(symbol);
            // `'<name>'` style symbols are display names, not spellings.
            // The wrapping test keeps real literals like `<` and `<=`.
            let display_only = inner.len() > 2 && inner.starts_with('<') && inner.ends_with('>');
            (!display_only).then_some(inner.to_string())
        });

        match literal {
            Some(literal) => {
                writeln!(variants, "    #[token({literal:?})]\n    {name},")
                    .expect("writing to a String cannot fail");
                writeln!(
                    literal_arms,
                    "            Self::{name} => Some({literal:?}),"
                )
                .expect("writing to a String cannot fail");
            }
            None => match spec.patterns.iter().find(|(pattern, _)| *pattern == name) {
                Some((_, arguments)) => {
                    writeln!(variants, "    #[regex({arguments})]\n    {name},")
                        .expect("writing to a String cannot fail");
                }
                None => missing.push(name.to_string()),
            },
        }
    }

    if !missing.is_empty() {
        return Err(invalid_data(format!(
            "tokens without literal spellings need a LexerSpec pattern: {}",
            missing.join(", ")
        )));
    }

    let generated = format!(
        r#"// Generated by lelwel::build_lexer from {grammar}. Do not edit.
use super::parser::{{Diagnostic, Span}};
use codespan_reporting::diagnostic::Label;
use logos::Logos;

#[derive(Debug, Clone, PartialEq, Default)]
pub enum LexerError {{
    #[default]
    Invalid,
}}

impl LexerError {{
    pub fn into_diagnostic(self, span: Span) -> Diagnostic {{
        match self {{
            Self::Invalid => Diagnostic::error()
                .with_message("invalid token")
                .with_label(Label::primary((), span)),
        }}
    }}
}}

#[derive(Logos, Debug, PartialEq, Copy, Clone)]
#[logos(error = LexerError)]
pub enum Token {{
    EOF,
    Error,
{variants}}}

impl Token {{
    /// The literal spelling of this token as declared in the grammar, for
    /// tokens that have one. Editor layers decide which are completions.
    pub const fn literal_text(self) -> Option<&'static str> {{
        match self {{
{literal_arms}            _ => None,
        }}
    }}
}}

pub fn tokenize(source: &str, diags: &mut Vec<Diagnostic>) -> (Vec<Token>, Vec<Span>) {{
    let lexer = Token::lexer(source);
    let mut tokens = vec![];
    let mut spans = vec![];

    for (token, span) in lexer.spanned() {{
        match token {{
            Ok(token) => {{
                tokens.push(token);
            }}
            Err(err) => {{
                diags.push(err.into_diagnostic(span.clone()));
                tokens.push(Token::Error);
            }}
        }}
        spans.push(span);
    }}
    (tokens, spans)
}}
"#
    );

    std::fs::write(Path::new(out_dir).join("lexer.rs"), generated)
}

fn invalid_data(message: String) -> std::io::Error {
    std::io::Error::new(std::io::ErrorKind::InvalidData, message)
}
